use rand::{distributions::Alphanumeric, Rng};
use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::{
    collections::BTreeMap,
    fs,
    path::PathBuf,
    sync::{Arc, RwLock},
    time::{SystemTime, UNIX_EPOCH},
};
fn now() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}
fn id(p: &str) -> String {
    format!(
        "{p}_{}",
        rand::thread_rng()
            .sample_iter(&Alphanumeric)
            .take(18)
            .map(char::from)
            .collect::<String>()
    )
}
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum EvidenceSourceType {
    User,
    ApplicationState,
    ExistingSchema,
    Connection,
    Artifact,
    Document,
    Provider,
    Agent,
    Workload,
    AiInference,
    SystemRule,
    ImportedData,
}
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ContractEvidence {
    pub evidence_id: String,
    pub source: String,
    pub source_type: EvidenceSourceType,
    pub statement: String,
    pub contract_paths: Vec<String>,
    pub confidence: f32,
    pub authority: String,
    pub provenance: Value,
    pub timestamp: u64,
    pub supporting_refs: Vec<String>,
    pub contradicting_refs: Vec<String>,
}
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum GapType {
    Missing,
    Ambiguous,
    Contradictory,
    Unauthorized,
    Unsupported,
    Unvalidated,
    DependencyMissing,
    ProviderMissing,
}
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ContractGap {
    pub contract_path: String,
    pub gap_type: GapType,
    pub severity: String,
    pub blocking: bool,
    pub confidence: f32,
    pub evidence_required: Vec<String>,
    pub suggested_questions: Vec<String>,
    pub candidate_resolutions: Vec<Value>,
    pub affected_paths: Vec<String>,
}
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ContractAssertion {
    pub value: Value,
    pub confidence: f32,
    pub evidence_refs: Vec<String>,
    pub required: bool,
    pub validated: bool,
}
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ApplicationContract {
    pub contract_id: String,
    pub application_id: String,
    pub base_revision: Option<String>,
    pub contract_revision: u64,
    pub status: String,
    pub assertions: BTreeMap<String, ContractAssertion>,
    pub evidence: Vec<ContractEvidence>,
    pub gaps: Vec<ContractGap>,
    pub created_at: u64,
    pub updated_at: u64,
}
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ContractChange {
    pub path: String,
    pub value: Value,
    pub confidence: f32,
    pub required: bool,
}
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ContractPatch {
    pub patch_id: Option<String>,
    pub base_revision: u64,
    pub changes: Vec<ContractChange>,
    pub evidence: Vec<ContractEvidence>,
    pub affected_paths: Vec<String>,
    pub confidence_delta: f32,
    pub risks: Vec<String>,
    pub provenance: Value,
}
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ContractReadiness {
    pub status: String,
    pub readiness: f32,
    pub blocking_gaps: usize,
    pub gaps: Vec<ContractGap>,
    pub confidence: BTreeMap<String, f32>,
    pub next_action: String,
}
#[derive(Default, Serialize, Deserialize)]
struct Records {
    contracts: BTreeMap<String, ApplicationContract>,
}
#[derive(Clone)]
pub struct ApplicationContractStore {
    path: PathBuf,
    records: Arc<RwLock<Records>>,
}
impl ApplicationContractStore {
    pub fn load(path: impl Into<PathBuf>) -> Result<Self, String> {
        let path = path.into();
        let records = if path.exists() {
            serde_json::from_slice(&fs::read(&path).map_err(|e| e.to_string())?)
                .map_err(|e| e.to_string())?
        } else {
            Records::default()
        };
        Ok(Self {
            path,
            records: Arc::new(RwLock::new(records)),
        })
    }
    fn persist(&self, r: &Records) -> Result<(), String> {
        if let Some(p) = self.path.parent() {
            fs::create_dir_all(p).map_err(|e| e.to_string())?
        }
        fs::write(
            &self.path,
            serde_json::to_vec_pretty(r).map_err(|e| e.to_string())?,
        )
        .map_err(|e| e.to_string())
    }
    pub fn get(&self, a: &str) -> Result<ApplicationContract, String> {
        self.records
            .read()
            .map_err(|_| "contract lock poisoned")?
            .contracts
            .get(a)
            .cloned()
            .ok_or("contract not found".into())
    }
    pub fn evaluate(
        &self,
        a: &str,
        outcome: &str,
        actor: &str,
    ) -> Result<ApplicationContract, String> {
        let mut r = self.records.write().map_err(|_| "contract lock poisoned")?;
        let t = now();
        let e = ContractEvidence {
            evidence_id: id("evidence"),
            source: actor.into(),
            source_type: EvidenceSourceType::User,
            statement: outcome.into(),
            contract_paths: vec!["outcome".into()],
            confidence: 0.99,
            authority: "subject".into(),
            provenance: serde_json::json!({"actor":actor}),
            timestamp: t,
            supporting_refs: vec![],
            contradicting_refs: vec![],
        };
        let mut assertions = BTreeMap::new();
        assertions.insert(
            "outcome".into(),
            ContractAssertion {
                value: Value::String(outcome.into()),
                confidence: 0.99,
                evidence_refs: vec![e.evidence_id.clone()],
                required: true,
                validated: true,
            },
        );
        let mut c = ApplicationContract {
            contract_id: id("contract"),
            application_id: a.into(),
            base_revision: None,
            contract_revision: 1,
            status: "INCOMPLETE".into(),
            assertions,
            evidence: vec![e],
            gaps: vec![],
            created_at: t,
            updated_at: t,
        };
        Self::recompute(&mut c);
        r.contracts.insert(a.into(), c.clone());
        self.persist(&r)?;
        Ok(c)
    }
    pub fn apply_patch(&self, a: &str, p: ContractPatch) -> Result<ApplicationContract, String> {
        let mut r = self.records.write().map_err(|_| "contract lock poisoned")?;
        let c = r.contracts.get_mut(a).ok_or("contract not found")?;
        if p.base_revision != c.contract_revision {
            return Err("stale contract patch".into());
        }
        if p.risks.iter().any(|x| x == "destructive")
            && !p
                .provenance
                .get("approved")
                .and_then(Value::as_bool)
                .unwrap_or(false)
        {
            return Err("destructive patch requires explicit approval".into());
        }
        for x in p.changes {
            if x.path.trim().is_empty() || !(0.0..=1.0).contains(&x.confidence) {
                return Err("invalid contract change".into());
            }
            if let Some(old) = c.assertions.get(&x.path) {
                if old.value != x.value && old.confidence > 0.8 && x.confidence > 0.8 {
                    c.gaps.push(ContractGap {
                        contract_path: x.path.clone(),
                        gap_type: GapType::Contradictory,
                        severity: "high".into(),
                        blocking: true,
                        confidence: x.confidence,
                        evidence_required: vec!["user resolution".into()],
                        suggested_questions: vec![format!("Which value should {} use?", x.path)],
                        candidate_resolutions: vec![old.value.clone(), x.value.clone()],
                        affected_paths: vec![x.path.clone()],
                    });
                    continue;
                }
            }
            c.assertions.insert(
                x.path,
                ContractAssertion {
                    value: x.value,
                    confidence: x.confidence,
                    evidence_refs: p.evidence.iter().map(|e| e.evidence_id.clone()).collect(),
                    required: x.required,
                    validated: true,
                },
            );
        }
        c.evidence.extend(p.evidence);
        c.contract_revision += 1;
        c.updated_at = now();
        Self::recompute(c);
        let out = c.clone();
        self.persist(&r)?;
        Ok(out)
    }
    fn recompute(c: &mut ApplicationContract) {
        c.gaps.retain(|g| g.gap_type == GapType::Contradictory);
        for p in ["outcome", "actors", "entities", "actions", "permissions"] {
            if !c.assertions.contains_key(p) {
                c.gaps.push(ContractGap {
                    contract_path: p.into(),
                    gap_type: GapType::Missing,
                    severity: "high".into(),
                    blocking: true,
                    confidence: 0.0,
                    evidence_required: vec!["contract evidence".into()],
                    suggested_questions: vec![match p {
                        "actors" => {
                            "Who will use this application, and what roles do they have?".into()
                        }
                        "entities" => {
                            "What information or records should the application keep track of?"
                                .into()
                        }
                        "actions" => "What should people be able to do with those records?".into(),
                        "permissions" => {
                            "Who can view, create, edit, delete, or administer this information?"
                                .into()
                        }
                        _ => format!("What should FeltDB understand about {p}?"),
                    }],
                    candidate_resolutions: vec![],
                    affected_paths: vec![p.into()],
                })
            }
        }
        c.status = Self::readiness_for(c).status
    }
    pub fn readiness(&self, a: &str) -> Result<ContractReadiness, String> {
        Ok(Self::readiness_for(&self.get(a)?))
    }
    pub fn next_question(&self, a: &str) -> Result<Option<ContractGap>, String> {
        let contract = self.get(a)?;
        Ok(contract
            .gaps
            .into_iter()
            .filter(|gap| gap.blocking)
            .min_by(|left, right| {
                left.confidence
                    .partial_cmp(&right.confidence)
                    .unwrap_or(std::cmp::Ordering::Equal)
            }))
    }
    pub fn end_session(&self, a: &str, actor: &str) -> Result<ApplicationContract, String> {
        let mut records = self.records.write().map_err(|_| "contract lock poisoned")?;
        let contract = records.contracts.get_mut(a).ok_or("contract not found")?;
        contract.status = "MANUALLY_ENDED".into();
        contract.updated_at = now();
        contract.evidence.push(ContractEvidence {
            evidence_id: id("evidence"),
            source: actor.into(),
            source_type: EvidenceSourceType::User,
            statement: "User ended contract completion; compose only evidenced assertions".into(),
            contract_paths: vec![],
            confidence: 1.0,
            authority: "subject".into(),
            provenance: serde_json::json!({"escape_hatch":true}),
            timestamp: now(),
            supporting_refs: vec![],
            contradicting_refs: vec![],
        });
        let result = contract.clone();
        self.persist(&records)?;
        Ok(result)
    }
    pub fn construction_input(&self, a: &str) -> Result<BTreeMap<String, Value>, String> {
        let contract = self.get(a)?;
        if contract.status != "READY" && contract.status != "MANUALLY_ENDED" {
            return Err("contract completion is still active".into());
        }
        Ok(contract
            .assertions
            .into_iter()
            .filter(|(_, assertion)| assertion.validated && !assertion.evidence_refs.is_empty())
            .map(|(path, assertion)| (path, assertion.value))
            .collect())
    }
    fn readiness_for(c: &ApplicationContract) -> ContractReadiness {
        let confidence = c
            .assertions
            .iter()
            .map(|(p, a)| (p.clone(), a.confidence))
            .collect::<BTreeMap<_, _>>();
        let readiness = if confidence.is_empty() {
            0.0
        } else {
            confidence.values().sum::<f32>() / confidence.len() as f32
        };
        let blocking = c.gaps.iter().filter(|g| g.blocking).count();
        ContractReadiness {
            status: if blocking > 0 {
                "INCOMPLETE"
            } else if readiness >= 0.75 {
                "READY"
            } else {
                "UNDERSTOOD"
            }
            .into(),
            readiness,
            blocking_gaps: blocking,
            gaps: c.gaps.clone(),
            confidence,
            next_action: if blocking > 0 { "CLARIFY" } else { "COMPOSE" }.into(),
        }
    }
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn contradiction_blocks() {
        let s = ApplicationContractStore::load(
            std::env::temp_dir().join(format!("contract-{}.json", now())),
        )
        .unwrap();
        s.evaluate("a", "Recruit", "u").unwrap();
        let p = ContractPatch {
            patch_id: None,
            base_revision: 1,
            changes: vec![ContractChange {
                path: "outcome".into(),
                value: Value::String("Sell".into()),
                confidence: 0.95,
                required: true,
            }],
            evidence: vec![],
            affected_paths: vec![],
            confidence_delta: 0.0,
            risks: vec![],
            provenance: serde_json::json!({}),
        };
        assert!(s
            .apply_patch("a", p)
            .unwrap()
            .gaps
            .iter()
            .any(|g| g.gap_type == GapType::Contradictory));
    }
    #[test]
    fn manual_end_constructs_only_evidenced_assertions() {
        let store = ApplicationContractStore::load(
            std::env::temp_dir().join(format!("contract-end-{}.json", now())),
        )
        .unwrap();
        store
            .evaluate("app", "Track approved work", "user")
            .unwrap();
        assert!(store.construction_input("app").is_err());
        store.end_session("app", "user").unwrap();
        let input = store.construction_input("app").unwrap();
        assert_eq!(input.len(), 1);
        assert!(input.contains_key("outcome"));
        assert!(!input.contains_key("entities"));
    }
}
